"""Generate global, local, fingerprint, stability, and domain artifacts."""
from __future__ import annotations
import json
from pathlib import Path
import joblib,numpy as np,pandas as pd,shap
from scipy import sparse
from src.explainability.global_explainer import model_importance
from src.explainability.fingerprint_mapper import map_morgan_bits
from src.ml.applicability_domain import applicability_domain
from src.ml.dataset_loader import load_feature_set,split_indices
def generate_explanations(root:Path):
 best=json.loads((root/"data/processed/xai_benchmarks/best_model.json").read_text()); model_id=best["model_id"]; parts=model_id.split("__"); feature=parts[1]; model=joblib.load(root/f"data/processed/xai_models/{model_id}.joblib"); feature_dir=root/"data/processed/xai_features"; x,y,index=load_feature_set(feature_dir,feature); schema=json.loads((feature_dir/"feature_schema.json").read_text()); names=schema["feature_names"]["descriptor"] if feature=="descriptor" else schema["feature_names"]["fingerprint"] if feature=="fingerprint" else schema["feature_names"]["descriptor"]+schema["feature_names"]["fingerprint"]+schema["feature_names"]["maccs"]
 global_dir=root/"data/processed/xai_explanations/global";global_dir.mkdir(parents=True,exist_ok=True);splits=split_indices(index);train,test=splits["train"],splits["test"]
 estimator=model.steps[-1][1] if hasattr(model,"steps") else model; transformed=model.steps[0][1].transform(x) if hasattr(model,"steps") else x; dense=transformed.toarray() if hasattr(transformed,"toarray") else np.asarray(transformed);explainer=shap.LinearExplainer(estimator,dense[train[:100]]);shap_values=np.asarray(explainer.shap_values(dense[test]));importance=sorted([{"feature":name,"importance":float(value),"direction":float(np.sign(np.mean(shap_values[:,i])))} for i,(name,value) in enumerate(zip(names,np.mean(np.abs(shap_values),axis=0)))],key=lambda row:row["importance"],reverse=True);pd.DataFrame(importance).to_csv(global_dir/"global_feature_importance.csv",index=False);pd.DataFrame([r for r in importance if not r["feature"].startswith(("Morgan_","MACCS_"))][:30]).to_csv(global_dir/"top_descriptor_features.csv",index=False);np.savez_compressed(global_dir/"fingerprint_shap_values.npz",values=shap_values)
 dataset=pd.read_csv(root/"data/processed/xai_dataset/hivpr_xai_2000_compounds.csv"); bits=[int(r["feature"].split("_")[1]) for r in importance if r["feature"].startswith("Morgan_")][:30]; fp_dir=root/"data/processed/xai_explanations/fingerprint";fp_dir.mkdir(parents=True,exist_ok=True);mapping=map_morgan_bits(dataset,bits);pd.DataFrame(mapping).to_csv(fp_dir/"fingerprint_bit_mapping.csv",index=False)
 pd.DataFrame([r for r in importance if r["feature"].startswith("Morgan_")][:30]).to_csv(global_dir/"top_fingerprint_bits.csv",index=False);morgan=sparse.load_npz(feature_dir/"morgan_features.npz").toarray().astype(bool);desc=pd.read_parquet(feature_dir/"descriptor_features.parquet").to_numpy();domain=applicability_domain(morgan[train],morgan[test],desc[train],desc[test],index.iloc[train].compound_id.tolist());domain_frame=pd.concat([index.iloc[test].reset_index(drop=True),pd.DataFrame(domain)],axis=1);pred_dir=root/"data/processed/xai_predictions";domain_frame.to_csv(pred_dir/"applicability_domain.csv",index=False)
 metrics=pd.read_csv(root/"data/processed/xai_benchmarks/model_comparison.csv");supported=metrics[(metrics.dataset_split=="validation")&(metrics.feature_set=="descriptor")&(metrics.model_name!="hist_gradient_boosting")];descriptor_id=supported.sort_values("pr_auc",ascending=False).iloc[0].model_id;descriptor_model=joblib.load(root/f"data/processed/xai_models/{descriptor_id}.joblib");descriptor_importance=model_importance(descriptor_model,schema["feature_names"]["descriptor"]);pd.DataFrame(descriptor_importance).to_csv(global_dir/"descriptor_importance.csv",index=False);pd.DataFrame(descriptor_importance[:30]).to_csv(global_dir/"top_descriptor_features.csv",index=False)
 pred=pd.read_csv(pred_dir/"test_predictions.csv");selected=pred[pred.model_id==model_id].copy(); selected=selected.sort_values("predicted_probability"); cards_dir=root/"data/processed/xai_explanations/local/compound_cards";cards_dir.mkdir(parents=True,exist_ok=True); chosen=pd.concat([selected.head(20),selected.tail(20),selected.iloc[(selected.predicted_probability-.5).abs().argsort()[:20]]]).drop_duplicates("compound_id");chosen.to_csv(root/"data/processed/xai_explanations/local/compound_explanations.csv",index=False)
 for row in chosen.to_dict("records"): (cards_dir/f"{row['compound_id']}.json").write_text(json.dumps({**row,"interpretation_warning":"Explains model behaviour, not biological causality."},indent=2))
 stability=root/"data/processed/xai_explanations/stability";stability.mkdir(parents=True,exist_ok=True);all_predictions=pd.read_csv(pred_dir/"test_predictions.csv");disagreement=all_predictions.groupby("compound_id").predicted_probability.agg(["mean","std","min","max"]).reset_index();disagreement.to_csv(stability/"model_disagreement.csv",index=False);disagreement.to_csv(stability/"local_stability.csv",index=False);pd.DataFrame([{"comparison":"repeated_seed_probabilities","mean_probability_sd":disagreement["std"].mean(),"warning":"Source shortcut caveat"}]).to_csv(stability/"global_stability.csv",index=False);(stability/"stability_summary.json").write_text(json.dumps({"mean_probability_standard_deviation":disagreement["std"].mean(),"unstable_compounds":int((disagreement["std"]>.1).sum())},indent=2))
 (global_dir/"global_explanation_manifest.json").write_text(json.dumps({"model_id":model_id,"top_features":30,"fingerprint_bits_mapped":len(mapping),"local_cards":len(chosen),"shap_limitation":"Native additive importances explain model behaviour, not biological causality."},indent=2));return {"model_id":model_id,"mapped_bits":len(mapping),"local_cards":len(chosen)}
